import{loadProducts}from'../core/api.js';import{card}from'../components/product-card.js';import{match}from'../components/search.js';import{filterProducts}from'../components/filters.js';import'../main.js';const items=await loadProducts();let cat=new URLSearchParams(location.search).get('cat')?.toUpperCase()||'ALLE',q='';const grid=document.querySelector('[data-catalog]');function draw(){grid.innerHTML=filterProducts(items,cat).filter(p=>match(p,q)).map(card).join('')||'<p>NICHT EINMAL UNSINN GEFUNDEN.</p>';document.querySelector('[data-result-count]').textContent=grid.children.length}draw();document.querySelector('[data-shop-search]').addEventListener('input',e=>{q=e.target.value;draw()});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{cat=b.dataset.filter;document.querySelector('.filters .active')?.classList.remove('active');b.classList.add('active');draw()}));
